INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 1, 'theory', 'Quiz: What Is Rust');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 1, 0, 'What does it mean that Rust is a compiled language?', '["An interpreter reads the program on every run", "The compiler turns the code into machine instructions ahead of time and produces an executable", "The program only works inside a browser", "The code cannot be run without the internet"]', 1, 'The rustc compiler checks types and memory and produces a file of machine instructions. You can run it without Rust installed.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 1, 1, 'What main problem does Rust solve?', '["Slow user interfaces", "A shortage of libraries", "Long function names", "Memory errors (out-of-bounds access, use after free, data races) — by forbidding them at build time"]', 3, 'By Microsoft and Chromium estimates, about 70% of serious vulnerabilities are memory-related. Rust removes this class of errors without a garbage collector.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 1, 2, 'When was the stable version Rust 1.0 released?', '["In 2006", "In 2021", "On May 15, 2015", "In 2022"]', 2, 'Graydon Hoare''s personal project began in 2006, Mozilla supported it from 2009, and 1.0 came out on May 15, 2015. Since then a new version ships every six weeks.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 1, 3, 'What does the cargo run command do?', '["Only checks the syntax", "Builds the project and runs the program", "Installs the compiler", "Deletes the project"]', 1, 'cargo build only builds, cargo check checks without producing a file, cargo new creates a project, and cargo run builds and runs it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 1, 4, 'What does the exclamation mark in println! mean?', '["An error", "Loud output", "End of line", "That it is a macro, not an ordinary function"]', 3, 'Macros are expanded at compile time and can take a variable number of arguments. println! substitutes values into {} and prints the line with a newline.');
